package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0)
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerFile *os.File
var ledgerScanner *bufio.Scanner
var ledgerRec LedgerRec

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatZZCommaZZ9_99(v decimal.Decimal) string {
	// PIC ZZ,ZZ9.99  width 9
	return formatEdited(v, "ZZ,ZZ9.99", false)
}

func formatBalEd(v decimal.Decimal) string {
	// PIC -Z,ZZZ,ZZ9.99 width 13, leading sign
	return formatEdited(v, "-Z,ZZZ,ZZ9.99", true)
}

func formatTotEd(v decimal.Decimal) string {
	// PIC -ZZZ,ZZZ,ZZ9.99 width 15
	return formatEdited(v, "-ZZZ,ZZZ,ZZ9.99", true)
}

// generic formatter for these patterns
func formatEdited(v decimal.Decimal, picture string, hasSign bool) string {
	width := len(picture)
	negative := v.Sign() < 0
	av := v.Abs()
	// truncate to 2 decimals (COBOL without ROUNDED truncates, but values already have 2)
	av = av.Truncate(2)

	// Get integer and fractional parts
	// av = intPart + frac/100
	// Use string formatting to avoid float
	// av.StringFixed(2) gives exactly 2 decimals
	s := av.StringFixed(2) // e.g. "1234.56"
	dot := strings.Index(s, ".")
	intStr := s[:dot]
	fracStr := s[dot+1:]
	if len(fracStr) < 2 {
		fracStr = fracStr + strings.Repeat("0", 2-len(fracStr))
	} else if len(fracStr) > 2 {
		fracStr = fracStr[:2]
	}

	// picture includes '.' at fixed position; integer picture part length = width -3 (".99" is 3)
	// But with sign, sign char occupies first position for "-"
	// For signed pictures, pattern starts with '-'
	picCore := picture
	signChar := ""
	if hasSign {
		// first char is '-'
		picCore = picture[1:] // rest
		if negative {
			signChar = "-"
		} else {
			signChar = " "
		}
	}

	// picCore width = width - (1 if hasSign else 0)
	// It contains digits, commas, dot
	// Find dot position
	dotPos := strings.Index(picCore, ".")
	intPic := picCore[:dotPos] // e.g. "ZZ,ZZ9" or "Z,ZZZ,ZZ9" etc
	// fracPic is "99" (2 chars)

	// Integer digit positions: count of Z and 9
	intDigitCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitCount++
		}
	}

	// If integer digits exceed allowed, drop high-order digits (COBOL overflow behavior)
	if len(intStr) > intDigitCount {
		intStr = intStr[len(intStr)-intDigitCount:]
	}
	// Left pad intStr with zeros to intDigitCount for mapping
	intStrPadded := strings.Repeat("0", intDigitCount-len(intStr)) + intStr

	// Build integer formatted part char by char
	// Map digit characters onto Z/9 positions
	digitIdx := 0
	intFormatted := make([]byte, len(intPic))
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		if ch == ',' {
			intFormatted[i] = ','
		} else if ch == 'Z' || ch == '9' {
			intFormatted[i] = intStrPadded[digitIdx]
			digitIdx++
		} else {
			intFormatted[i] = byte(ch)
		}
	}

	// Apply Z suppression: leading zeros replaced by spaces, commas in suppressed zone become spaces
	// Suppression runs over the integer part left to right until last leading zero before a non-zero
	// For Z positions: if digit is '0' and all previous digit positions were zero (or suppressed), replace with space
	// For picture, 9 is never suppressed
	// Need to handle digit positions in order
	// Determine digit positions indexes in intFormatted
	// Iterate over intPic positions that are Z/9 in order
	suppressing := true
	for i := 0; i < len(intPic); i++ {
		ch := intPic[i]
		if ch == ',' {
			continue
		}
		if ch == 'Z' {
			if suppressing && intFormatted[i] == '0' {
				intFormatted[i] = ' '
			} else {
				suppressing = false
			}
		} else if ch == '9' {
			// 9 never suppressed, and ends suppression
			suppressing = false
		}
	}
	// After suppression, commas that are in the suppressed leading area become spaces
	// A comma becomes space if all digit positions to its left are spaces (i.e. suppressed) ?
	// Actually COBOL: comma inside suppressed zone also becomes space.
	// So scan left to right: if comma and every digit to left is space, then space
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == ',' {
			// check if any non-space digit to left
			hasDigit := false
			for j := 0; j < i; j++ {
				if intPic[j] != ',' && intFormatted[j] != ' ' {
					hasDigit = true
					break
				}
			}
			if !hasDigit {
				intFormatted[i] = ' '
			}
		}
	}

	// Assemble integer part + "." + fractional part
	core := string(intFormatted) + "." + fracStr

	if hasSign {
		return signChar + core
	}
	return core
}

func main() {
	var err error
	ledgerFile, err = os.Open("input.dat")
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		// file not exist -> treat as empty
		ledgerScanner = bufio.NewScanner(strings.NewReader(""))
	} else {
		defer ledgerFile.Close()
		ledgerScanner = bufio.NewScanner(ledgerFile)
	}
	// allow long lines
	MAIN_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT LEDGER-FILE
	READ_PARA()
	for !isInputDone() {
		PROCESS_PARA()
	}
	if !isFirstRecord() {
		ACCT_BREAK_PARA()
		BRANCH_BREAK_PARA()
	}
	if ledgerFile != nil {
		ledgerFile.Close()
	}
	GRAND_PARA()
}

func READ_PARA() {
	if ledgerScanner.Scan() {
		line := ledgerScanner.Text()
		// pad with spaces to record length 14
		if len(line) < 14 {
			line = line + strings.Repeat(" ", 14-len(line))
		}
		if len(line) > 14 {
			line = line[:14]
		}
		ledgerRec.BrBranch = line[0:2]
		ledgerRec.BrAcct = line[2:6]
		ledgerRec.BrType = line[6:7]
		amtStr := line[7:14]
		// digits only
		amtStr = strings.TrimSpace(amtStr)
		if amtStr == "" {
			amtStr = "0"
		}
		// amtStr may contain spaces? but per spec digits only. Parse as integer.
		n := decimal.NewFromInt(0)
		// Use decimal require parse
		// Remove leading zeros spaces
		amtStrTrim := strings.TrimSpace(line[7:14])
		if amtStrTrim == "" {
			n = decimal.NewFromInt(0)
		} else {
			// parse digits
			parsed, err := decimal.NewFromString(amtStrTrim)
			if err != nil {
				// fallback
				parsed = decimal.NewFromInt(0)
			}
			n = parsed
		}
		ledgerRec.BrAmt = decimal.New(n.IntPart(), -2)
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			ACCT_BREAK_PARA()
			BRANCH_BREAK_PARA()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				ACCT_BREAK_PARA()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	POST_PARA()
	READ_PARA()
}

func POST_PARA() {
	WsAmtEd = formatZZCommaZZ9_99(ledgerRec.BrAmt)
	switch ledgerRec.BrType {
	case "D":
		WsBal = WsBal.Add(ledgerRec.BrAmt)
		fmt.Printf("%s D %s\n", ledgerRec.BrAcct, WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(ledgerRec.BrAmt)
		fmt.Printf("%s C %s\n", ledgerRec.BrAcct, WsAmtEd)
	default:
		WsSkipped++
		fmt.Printf("%s ? SKIPPED\n", ledgerRec.BrAcct)
	}
}

func ACCT_BREAK_PARA() {
	WsBalEd = formatBalEd(WsBal)
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	WsBranchTot = WsBranchTot.Add(WsBal)
	WsBal = decimal.NewFromInt(0)
}

func BRANCH_BREAK_PARA() {
	WsTotEd = formatTotEd(WsBranchTot)
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	WsGrandTot = WsGrandTot.Add(WsBranchTot)
	WsBranchTot = decimal.NewFromInt(0)
}

func GRAND_PARA() {
	WsTotEd = formatTotEd(WsGrandTot)
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	fmt.Printf("SKIPPED: %02d\n", WsSkipped)
}

